INSERT INTO policy_constants (key,item,value_text,numbers,condition,source_title,source_url,source_date,effective_from,verified_at,status,note) VALUES
('acq_tax_gift','주택 무상취득(증여) 취득세 — 표준세율','3.5%',ARRAY['3.5%'],'상속 외 무상취득. 비영리사업자는 2.8%(이 계산기 밖). 과세표준은 시가인정액(§10의2①)','지방세법 제11조제1항제2호 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제11조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_gift_heavy_12','조정대상지역 주택 무상취득 중과세율','12%',ARRAY['12%'],'조정대상지역 & 시가표준액 3억원 이상. 1세대1주택자의 주택을 배우자·직계존비속이 무상취득하면 제외(시행령 §28의6②1). 받는 사람의 주택 수는 요건이 아니다','지방세법 제13조의2제2항 · 시행령 제28조의6 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제13조의2','2026-07-01','2020-08-12','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 4% + 중과기준세율×400%. 지방교육세 0.4%(§151①1나)'),
('acq_tax_gift_heavy_min','무상취득 중과 문턱 — 시가표준액','3억원',ARRAY['3억원'],'취득 당시 시가표준액(지분·부속토지만 취득하면 전체 주택의 시가표준액) 3억원 이상','지방세법 시행령 제28조의6제1항 (현행 시행본)','https://www.law.go.kr/법령/지방세법시행령/제28조의6','2026-07-01','2020-08-12','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_inherit','상속 취득세(농지 외)','2.8%',ARRAY['2.8%'],'상속으로 인한 취득, 농지 외. 농지는 2.3%(이 계산기 밖). 과세표준은 시가표준액(§10의2②1)','지방세법 제11조제1항제1호나목 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제11조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_inherit_1house','상속 1가구1주택 취득세 특례','0.8%',ARRAY['0.8%'],'상속인 기준 1가구 1주택(시행령 §29). 2.8% − 중과기준세율 2%. 농특세 비과세(농특세법 §4 10의4)','지방세법 제15조제1항제2호가목 · 시행령 제29조 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제15조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_std_rate','중과기준세율','2%',ARRAY['2%'],'취득세 세율 가감·특례의 기준 세율(1천분의 20). 지방교육세·농특세 산식에 쓰인다','지방세법 제6조제19호 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제6조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_edu_ratio','지방교육세(취득분) — (세율 − 중과기준세율) 산출액의 비율','20%',ARRAY['20%'],'증여·상속: 과세표준×(§11 세율 − 2%)×20%. 유상주택은 세율×50%×20%. §13의2 중과는 (4%−2%)×20%','지방세법 제151조제1항제1호 (현행 시행본)','https://www.law.go.kr/법령/지방세법/제151조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 단위는 «산출액 대비 %». 감면율이 정해진 감면은 같은 율로 감면(다목1)'),
('acq_tax_farm_ratio','농어촌특별세(취득세분) — 표준세율 2% 적용 취득세액의 비율','10%',ARRAY['10%'],'전용 85㎡ 이하(서민주택) 비과세(§4 11호·시행령 §4⑤). 표준 0.2% · 중과 12%는 (2%+8%)×10%=1.0%','농어촌특별세법 제5조제1항제6호 (현행 시행본)','https://www.law.go.kr/법령/농어촌특별세법/제5조','2026-05-12',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 중과식 대입은 원문 산식 해석(고시 미확인)'),
('acq_tax_farm_relief','농어촌특별세 — 감면받은 취득세액의 비율','20%',ARRAY['20%'],'지방세특례제한법 등으로 감면받은 취득세액 × 20%. 서민주택(85㎡ 이하) 감면은 비과세(§4 9호)','농어촌특별세법 제5조제1항제1호 (현행 시행본)','https://www.law.go.kr/법령/농어촌특별세법/제5조','2026-05-12',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_firsthome_cap','생애최초 주택 구입 취득세 감면 한도 — 일반(2028-12-31까지)','200만원',ARRAY['200만원'],'본인·배우자 무주택, 본인 거주 목적, 유상거래(부담부증여 제외), 취득당시가액 12억원 이하, 미성년자 제외. 산출 취득세액에만 적용(200만원 이하면 면제)','지방세특례제한법 제36조의3제1항제2호 (현행 시행본)','https://www.law.go.kr/법령/지방세특례제한법/제36조의3','2026-06-02','2026-01-01','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 일몰 2028-12-31(법률 21309, 2026-01-01 시행). 3년 내 매각·증여·임대 시 추징'),
('acq_tax_firsthome_cap_300','생애최초 주택 구입 취득세 감면 한도 — 소형 비아파트·인구감소지역(2028-12-31까지)','300만원',ARRAY['300만원'],'60㎡ 이하 & 3억원(수도권 6억원) 이하 공동주택(아파트 제외)·도시형 생활주택·다가구 호수, 또는 인구감소지역 소재 주택(라목 2026 신설)','지방세특례제한법 제36조의3제1항제1호 (현행 시행본)','https://www.law.go.kr/법령/지방세특례제한법/제36조의3','2026-06-02','2026-01-01','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 일몰 2028-12-31'),
('acq_tax_firsthome_max','생애최초 감면 — 취득당시가액 상한','12억원',ARRAY['12억원'],'취득당시가액(지방세법 §10의3) 12억원 이하','지방세특례제한법 제36조의3제1항 (현행 시행본)','https://www.law.go.kr/법령/지방세특례제한법/제36조의3','2026-06-02','2026-01-01','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('acq_tax_unsold_local','지방 준공후미분양 아파트 취득세 경감률(2026-12-31까지)','25%',ARRAY['25%'],'수도권 외 · 전용 85㎡ 이하 · 취득당시가액 6억원 이하 · 사업주체로부터 최초 유상거래(부담부증여 제외) · 법인·단체 제외 · 실제 입주 1년 미만. 조례로 25% 범위 추가 경감(⑤)','지방세특례제한법 제33조의3제4항 (현행 시행본)','https://www.law.go.kr/법령/지방세특례제한법/제33조의3','2026-06-02','2025-12-31','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조 · 세율 특례가 아니라 취득세 경감. 지방교육세도 같은 율로 감면(지방세법 §151①1다1). 법률 21309 부칙 §1 1호'),
('acq_tax_unsold_local_max','지방 준공후미분양 경감 — 취득당시가액 상한','6억원',ARRAY['6억원'],'취득당시가액(지방세법 §10의3) 6억원 이하','지방세특례제한법 제33조의3제4항제4호 (현행 시행본)','https://www.law.go.kr/법령/지방세특례제한법/제33조의3','2026-06-02','2025-12-31','2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
('prop_tax_fmv','재산세 공정시장가액비율 — 주택(일반)','60%',ARRAY['60%'],'주택 시가표준액의 60%','지방세법 시행령 제109조제1항제2호 (현행 시행본)','https://www.law.go.kr/법령/지방세법시행령/제109조','2026-07-01',NULL,'2026-09-17','confirmed','K-9 local. DRF eflaw 현행 원문 직접 대조'),
