-- K-9 local — 지방세 6계산기 policy_constants 41행 (적용: MCP apply_migration k9_local_policy_constants_2026_09_17)
-- 국가법령정보센터 DRF eflaw «현행 시행본» XML 직접 대조(2026-09-17): 지방세법 MST 282559(2026-07-01) · 시행령 MST 287223(2026-07-01)
--   · 지특법 MST 286607(2026-06-02) · 농특세법 MST 285905(2026-05-12) · 인지세법 MST 276139(2026-01-02).
--   시행예정판(지방세법 2027-01-01/2027-09-09 · 시행령 2026-09-18 · 지특법 2027-09-09)의 같은 조문은 현행과 문언 동일.
-- ⚠️ 일몰일은 item 의 「YYYY-MM-DD까지」로 싣는다 — 계산기가 그 문자열을 읽는다(파서는 numbers 첫 원소만 읽음).
-- ⚠️ 신규 키가 이미 있으면 중단(덮어쓰지 않는다). 말미 단언: 신규 41행 + 기존 acq_tax 5행 무변경.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM policy_constants WHERE key IN ('acq_tax_gift','acq_tax_gift_heavy_12','acq_tax_gift_heavy_min','acq_tax_inherit','acq_tax_inherit_1house','acq_tax_std_rate','acq_tax_edu_ratio','acq_tax_farm_ratio','acq_tax_farm_relief','acq_tax_firsthome_cap','acq_tax_firsthome_cap_300','acq_tax_firsthome_max','acq_tax_unsold_local','acq_tax_unsold_local_max','prop_tax_fmv','prop_tax_fmv_1h_3eok','prop_tax_fmv_1h_6eok','prop_tax_fmv_1h_over','prop_tax_1h_band_3eok','prop_tax_1h_band_6eok','prop_tax_1h_rate_cap','prop_tax_city','prop_tax_edu','reg_lic_mortgage','reg_lic_jeonse','reg_lic_seizure','reg_lic_other','reg_lic_edu','stamp_duty_1k_3k','stamp_duty_3k_5k','stamp_duty_5k_1eok','stamp_duty_1eok_10eok','stamp_duty_over_10eok','stamp_duty_house_exempt','stamp_duty_loan_exempt','veh_tax_cc_1000','veh_tax_cc_1600','veh_tax_cc_over','veh_tax_age_step','veh_tax_other_car','veh_tax_edu')) THEN RAISE EXCEPTION 'k9_local: 신규 키가 이미 존재'; END IF;
END $$;
DO $$ DECLARE c int; a int; BEGIN
  SELECT count(*) INTO c FROM policy_constants WHERE key IN ('acq_tax_gift','acq_tax_gift_heavy_12','acq_tax_gift_heavy_min','acq_tax_inherit','acq_tax_inherit_1house','acq_tax_std_rate','acq_tax_edu_ratio','acq_tax_farm_ratio','acq_tax_farm_relief','acq_tax_firsthome_cap','acq_tax_firsthome_cap_300','acq_tax_firsthome_max','acq_tax_unsold_local','acq_tax_unsold_local_max','prop_tax_fmv','prop_tax_fmv_1h_3eok','prop_tax_fmv_1h_6eok','prop_tax_fmv_1h_over','prop_tax_1h_band_3eok','prop_tax_1h_band_6eok','prop_tax_1h_rate_cap','prop_tax_city','prop_tax_edu','reg_lic_mortgage','reg_lic_jeonse','reg_lic_seizure','reg_lic_other','reg_lic_edu','stamp_duty_1k_3k','stamp_duty_3k_5k','stamp_duty_5k_1eok','stamp_duty_1eok_10eok','stamp_duty_over_10eok','stamp_duty_house_exempt','stamp_duty_loan_exempt','veh_tax_cc_1000','veh_tax_cc_1600','veh_tax_cc_over','veh_tax_age_step','veh_tax_other_car','veh_tax_edu') AND status='confirmed';
  IF c <> 41 THEN RAISE EXCEPTION 'k9_local: 신규 행 수 불일치 %', c; END IF;
  SELECT count(*) INTO a FROM policy_constants WHERE key IN ('acq_tax_1house_6eok_under','acq_tax_1house_6_9eok','acq_tax_1house_9eok_over','acq_tax_heavy_8','acq_tax_heavy_12') AND status='confirmed';
  IF a <> 5 THEN RAISE EXCEPTION 'k9_local: 기존 acq_tax 5행 불일치 %', a; END IF;
END $$;
